/* =========================================================
   SIGFRIED BRETON — COMPLETE PORTFOLIO
   Version 4.0
   Navigation, GitHub API, Project Filtering & Interactions
========================================================= */

(function () {
  "use strict";

  /* =====================================================
       01. INITIALIZATION
    ===================================================== */

  const html = document.documentElement;

  html.classList.remove("no-js");
  html.classList.add("js");

  /* =====================================================
       02. ELEMENT REFERENCES
    ===================================================== */

  const header = document.querySelector(".site-header");

  const navToggle = document.querySelector(".nav-toggle");

  const siteNav = document.querySelector(".site-nav");

  const progressBar = document.getElementById("reading-progress");

  const backToTop = document.getElementById("back-to-top");

  const currentYear = document.getElementById("current-year");

  /* =====================================================
       03. MOBILE NAVIGATION
    ===================================================== */

  function setMenuState(isOpen) {
    if (!navToggle || !siteNav) {
      return;
    }

    navToggle.setAttribute("aria-expanded", String(isOpen));

    navToggle.setAttribute(
      "aria-label",
      isOpen ? "Close navigation menu" : "Open navigation menu",
    );

    siteNav.classList.toggle("is-open", isOpen);
  }

  if (navToggle && siteNav) {
    navToggle.addEventListener("click", function () {
      const isOpen = navToggle.getAttribute("aria-expanded") === "true";

      setMenuState(!isOpen);
    });

    /* Close navigation after selecting a link */

    siteNav.querySelectorAll('a[href^="#"]').forEach(function (link) {
      link.addEventListener("click", function () {
        setMenuState(false);
      });
    });

    /* Close navigation using Escape */

    document.addEventListener("keydown", function (event) {
      if (event.key === "Escape") {
        setMenuState(false);
      }
    });

    /* Close navigation when clicking outside */

    document.addEventListener("click", function (event) {
      const isOpen = navToggle.getAttribute("aria-expanded") === "true";

      if (isOpen && header && !header.contains(event.target)) {
        setMenuState(false);
      }
    });

    /* Close when switching to desktop width */

    window.addEventListener("resize", function () {
      if (window.innerWidth > 850) {
        setMenuState(false);
      }
    });
  }

  /* =====================================================
       04. SCROLL PROGRESS & HEADER
    ===================================================== */

  let scrollScheduled = false;

  function updateScrollUI() {
    if (scrollScheduled) {
      return;
    }

    scrollScheduled = true;

    window.requestAnimationFrame(function () {
      const scrollTop = window.scrollY || document.documentElement.scrollTop;

      const documentHeight = document.documentElement.scrollHeight;

      const windowHeight = window.innerHeight;

      const scrollableHeight = documentHeight - windowHeight;

      /* Reading progress */

      let progress = 0;

      if (scrollableHeight > 0) {
        progress = (scrollTop / scrollableHeight) * 100;
      }

      progress = Math.max(0, Math.min(100, progress));

      if (progressBar) {
        progressBar.style.width = progress + "%";
      }

      /* Header shadow */

      if (header) {
        header.classList.toggle("scrolled", scrollTop > 20);
      }

      /* Back-to-top visibility */

      if (backToTop) {
        backToTop.classList.toggle("is-visible", scrollTop > 450);
      }

      scrollScheduled = false;
    });
  }

  window.addEventListener("scroll", updateScrollUI, { passive: true });

  window.addEventListener("resize", updateScrollUI, { passive: true });

  updateScrollUI();

  /* =====================================================
       05. BACK TO TOP
    ===================================================== */

  if (backToTop) {
    backToTop.addEventListener("click", function () {
      window.scrollTo({
        top: 0,

        behavior: "smooth",
      });
    });
  }

  /* =====================================================
       06. SCROLL REVEAL ANIMATIONS
    ===================================================== */

  const revealElements = document.querySelectorAll("[data-reveal]");

  const prefersReducedMotion = window.matchMedia(
    "(prefers-reduced-motion: reduce)",
  ).matches;

  if (prefersReducedMotion || !("IntersectionObserver" in window)) {
    revealElements.forEach(function (element) {
      element.classList.add("is-visible");
    });
  } else {
    const revealObserver = new IntersectionObserver(
      function (entries, observer) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-visible");

            observer.unobserve(entry.target);
          }
        });
      },

      {
        threshold: 0.08,

        rootMargin: "0px 0px -30px 0px",
      },
    );

    revealElements.forEach(function (element) {
      revealObserver.observe(element);
    });
  }

  /* =====================================================
       07. ACTIVE NAVIGATION
    ===================================================== */

  const navigationLinks = document.querySelectorAll('.site-nav a[href^="#"]');

  const trackedSections = document.querySelectorAll(
    "#home, #about, #skills, #projects, #github, #experience, #education, #contact",
  );

  function setActiveNavigation(sectionId) {
    navigationLinks.forEach(function (link) {
      const target = link.getAttribute("href");

      const isActive = target === "#" + sectionId;

      link.classList.toggle("is-active", isActive);
    });
  }

  if ("IntersectionObserver" in window) {
    const navigationObserver = new IntersectionObserver(
      function (entries) {
        const visibleSections = entries

          .filter(function (entry) {
            return entry.isIntersecting;
          })

          .sort(function (a, b) {
            return b.intersectionRatio - a.intersectionRatio;
          });

        if (visibleSections.length > 0) {
          setActiveNavigation(visibleSections[0].target.id);
        }
      },

      {
        root: null,

        rootMargin: "-20% 0px -65% 0px",

        threshold: [0, 0.1, 0.25, 0.5],
      },
    );

    trackedSections.forEach(function (section) {
      navigationObserver.observe(section);
    });
  }

  /* =====================================================
       08. PROJECT FILTERING
    ===================================================== */

  const filterButtons = document.querySelectorAll(".filter-button");

  const projectCards = document.querySelectorAll(
    ".project-card[data-category]",
  );

  const filterStatus = document.querySelector(".project-filter-status");

  const emptyProjects = document.getElementById("projects-empty");

  function filterProjects(category) {
    let visibleCount = 0;

    projectCards.forEach(function (card) {
      const projectCategory = card.getAttribute("data-category");

      const shouldDisplay = category === "all" || projectCategory === category;

      card.classList.toggle("is-filtered", !shouldDisplay);

      if (shouldDisplay) {
        visibleCount++;

        card.classList.add("is-visible");
      }
    });

    /* Empty state */

    if (emptyProjects) {
      emptyProjects.hidden = visibleCount !== 0;
    }

    /* Status text */

    if (filterStatus) {
      const labels = {
        all: "Showing all projects",

        institutional: "Showing institutional projects",

        client: "Showing client projects",

        education: "Showing educational projects",
      };

      filterStatus.textContent = labels[category] || "Showing all projects";
    }
  }

  filterButtons.forEach(function (button) {
    button.addEventListener("click", function () {
      const category = button.getAttribute("data-filter");

      filterButtons.forEach(function (item) {
        const isActive = item === button;

        item.classList.toggle("is-active", isActive);

        item.setAttribute("aria-pressed", String(isActive));
      });

      filterProjects(category);
    });
  });

  /* Initial state */

  filterProjects("all");

  /* =====================================================
       09. GITHUB CONFIGURATION
    ===================================================== */

  const GITHUB_USERNAME = "sigfried0909";

  const GITHUB_API = "https://api.github.com";

  const GITHUB_PROFILE_URL =
    GITHUB_API + "/users/" + encodeURIComponent(GITHUB_USERNAME);

  const GITHUB_REPOSITORY_URL =
    GITHUB_API +
    "/users/" +
    encodeURIComponent(GITHUB_USERNAME) +
    "/repos?type=owner&sort=updated&per_page=100&page=1";

  const GITHUB_PUBLIC_PROFILE = "https://github.com/" + GITHUB_USERNAME;

  const GITHUB_REPOSITORIES_PAGE = GITHUB_PUBLIC_PROFILE + "?tab=repositories";

  /* GitHub statistics elements */

  const githubStats = {
    repositories: document.getElementById("github-repo-count"),

    followers: document.getElementById("github-followers"),

    following: document.getElementById("github-following"),

    gists: document.getElementById("github-public-gists"),
  };

  /* GitHub containers */

  const githubContainer = document.getElementById("github-repositories");

  const githubStatus = document.getElementById("github-status");

  let githubRequestStarted = false;

  /* =====================================================
       10. GITHUB STATUS INDICATOR
    ===================================================== */

  function updateGitHubStatus(message, state) {
    if (!githubStatus) {
      return;
    }

    githubStatus.className = "github-load-status";

    if (state === "connected") {
      githubStatus.classList.add("is-connected");
    }

    if (state === "error") {
      githubStatus.classList.add("is-error");
    }

    githubStatus.textContent = "";

    const indicator = document.createElement("i");

    const label = document.createTextNode(message);

    githubStatus.appendChild(indicator);

    githubStatus.appendChild(label);
  }

  /* =====================================================
       11. NUMBER FORMATTER
    ===================================================== */

  function formatNumber(value) {
    const number = Number(value);

    if (!Number.isFinite(number)) {
      return "0";
    }

    return new Intl.NumberFormat("en-US").format(number);
  }

  /* =====================================================
       12. DATE FORMATTER
    ===================================================== */

  function formatGitHubDate(dateValue) {
    if (!dateValue) {
      return "Date unavailable";
    }

    const date = new Date(dateValue);

    if (Number.isNaN(date.getTime())) {
      return "Date unavailable";
    }

    return new Intl.DateTimeFormat(
      "en-US",

      {
        year: "numeric",

        month: "short",

        day: "numeric",
      },
    ).format(date);
  }

  /* =====================================================
       13. GITHUB FETCH HELPER
    ===================================================== */

  async function fetchGitHubJSON(url) {
    const controller = new AbortController();

    const timeout = window.setTimeout(function () {
      controller.abort();
    }, 12000);

    try {
      const response = await fetch(
        url,

        {
          method: "GET",

          headers: {
            Accept: "application/vnd.github+json",

            "X-GitHub-Api-Version": "2022-11-28",
          },

          signal: controller.signal,
        },
      );

      if (!response.ok) {
        throw new Error("GitHub API returned HTTP " + response.status);
      }

      return await response.json();
    } finally {
      window.clearTimeout(timeout);
    }
  }

  /* =====================================================
       14. UPDATE GITHUB STATISTICS
    ===================================================== */

  function updateGitHubStats(profile) {
    if (!profile || typeof profile !== "object") {
      return;
    }

    const values = {
      repositories: profile.public_repos,

      followers: profile.followers,

      following: profile.following,

      gists: profile.public_gists,
    };

    Object.keys(githubStats).forEach(function (key) {
      const element = githubStats[key];

      if (!element) {
        return;
      }

      const value = Number(values[key]);

      if (Number.isFinite(value)) {
        element.textContent = formatNumber(value);
      }
    });
  }

  /* =====================================================
       15. SAFE GITHUB URL VALIDATION
    ===================================================== */

  function getSafeRepositoryURL(urlValue) {
    try {
      const url = new URL(urlValue);

      if (
        url.protocol !== "https:" ||
        url.hostname.toLowerCase() !== "github.com"
      ) {
        return null;
      }

      return url.href;
    } catch (error) {
      return null;
    }
  }

  /* =====================================================
       16. CREATE GITHUB REPOSITORY CARD
    ===================================================== */

  function createRepositoryCard(repository) {
    const article = document.createElement("article");

    article.className = "github-repo-card";

    /* Header */

    const header = document.createElement("div");

    header.className = "github-repo-top";

    const name = document.createElement("a");

    name.className = "github-repo-name";

    const repositoryURL = getSafeRepositoryURL(repository.html_url);

    if (repositoryURL) {
      name.href = repositoryURL;

      name.target = "_blank";

      name.rel = "noopener noreferrer";
    }

    name.textContent = repository.name || "Unnamed Repository";

    const visibility = document.createElement("span");

    visibility.className = "github-repo-visibility";

    visibility.textContent = "PUBLIC";

    header.appendChild(name);

    header.appendChild(visibility);

    /* Description */

    const description = document.createElement("p");

    description.className = "github-repo-description";

    description.textContent =
      repository.description || "No description provided for this repository.";

    /* Footer */

    const footer = document.createElement("div");

    footer.className = "github-repo-footer";

    /* Programming language */

    const language = document.createElement("span");

    language.className = "github-repo-language";

    if (repository.language) {
      const dot = document.createElement("i");

      dot.className = "github-language-dot";

      language.appendChild(dot);

      language.appendChild(document.createTextNode(repository.language));
    } else {
      language.textContent = "Language not specified";
    }

    /* Repository metadata */

    const meta = document.createElement("div");

    meta.className = "github-repo-meta";

    const stars = document.createElement("span");

    stars.textContent = "★ " + formatNumber(repository.stargazers_count);

    const forks = document.createElement("span");

    forks.textContent = "⑂ " + formatNumber(repository.forks_count);

    meta.appendChild(stars);

    meta.appendChild(forks);

    footer.appendChild(language);

    footer.appendChild(meta);

    /* Updated date */

    const updated = document.createElement("span");

    updated.className = "github-repo-meta";

    updated.textContent = "Updated " + formatGitHubDate(repository.updated_at);

    /* Assemble */

    article.appendChild(header);

    article.appendChild(description);

    article.appendChild(footer);

    article.appendChild(updated);

    return article;
  }

  /* =====================================================
       17. NORMALIZE REPOSITORY TEXT
    ===================================================== */

  function normalizeRepositoryText(value) {
    return String(value || "")
      .toLowerCase()

      .replace(/[^a-z0-9]/g, "");
  }

  /* =====================================================
       18. FIND FEATURED PROJECT REPOSITORIES
    ===================================================== */

  const featuredRepositoryRules = {
    acadtrack: {
      aliases: ["acadtrack", "academictracking", "studentpermitmonitoring"],

      fallbackText: "Find AcadTrack on GitHub ↗",
    },

    barangay: {
      aliases: [
        "barangaytatalonmis",

        "barangaytatalon",

        "tatalonmis",

        "tatalon",

        "barangaymis",
      ],

      fallbackText: "Find Barangay MIS on GitHub ↗",
    },
  };

  function findFeaturedRepository(repositories, projectKey) {
    const rule = featuredRepositoryRules[projectKey];

    if (!rule) {
      return null;
    }

    /*
     * First match repository name.
     * Then use description as a fallback.
     */

    const nameMatch = repositories.find(function (repository) {
      const name = normalizeRepositoryText(repository.name);

      return rule.aliases.some(function (alias) {
        const normalizedAlias = normalizeRepositoryText(alias);

        return name.includes(normalizedAlias);
      });
    });

    if (nameMatch) {
      return nameMatch;
    }

    const descriptionMatch = repositories.find(function (repository) {
      const description = normalizeRepositoryText(repository.description);

      return rule.aliases.some(function (alias) {
        const normalizedAlias = normalizeRepositoryText(alias);

        return description.includes(normalizedAlias);
      });
    });

    return descriptionMatch || null;
  }

  /* =====================================================
       19. CONNECT FEATURED PROJECT LINKS
    ===================================================== */

  function matchFeaturedProjectRepositories(repositories) {
    const featuredLinks = document.querySelectorAll(
      ".github-project-link[data-github-match]",
    );

    featuredLinks.forEach(function (link) {
      const projectKey = link.getAttribute("data-github-match");

      const rule = featuredRepositoryRules[projectKey];

      if (!rule) {
        return;
      }

      const repository = findFeaturedRepository(repositories, projectKey);

      if (repository) {
        const safeURL = getSafeRepositoryURL(repository.html_url);

        if (safeURL) {
          link.href = safeURL;

          link.textContent = repository.name + " Repository ↗";

          link.setAttribute("data-repository-found", "true");

          return;
        }
      }

      /*
       * If no matching repository is found,
       * send visitors to the public repositories list.
       * Do not invent a repository URL.
       */

      link.href = GITHUB_REPOSITORIES_PAGE;

      link.textContent = rule.fallbackText;

      link.setAttribute("data-repository-found", "false");
    });
  }

  /* =====================================================
       20. RENDER PUBLIC REPOSITORIES
    ===================================================== */

  function renderGitHubRepositories(repositories) {
    if (!githubContainer) {
      return;
    }

    githubContainer.innerHTML = "";

    githubContainer.setAttribute("aria-busy", "false");

    if (!Array.isArray(repositories) || repositories.length === 0) {
      const message = document.createElement("div");

      message.className = "github-error-card";

      const paragraph = document.createElement("p");

      paragraph.textContent = "No public repositories are currently available.";

      message.appendChild(paragraph);

      githubContainer.appendChild(message);

      return;
    }

    const fragment = document.createDocumentFragment();

    /*
     * Display up to eight latest public repositories.
     * Public forks are included when owned by this account.
     */

    const displayedRepositories = repositories.slice(0, 8);

    displayedRepositories.forEach(function (repository) {
      if (!repository || typeof repository !== "object" || repository.private) {
        return;
      }

      fragment.appendChild(createRepositoryCard(repository));
    });

    if (!fragment.childNodes.length) {
      const message = document.createElement("div");

      message.className = "github-error-card";

      const paragraph = document.createElement("p");

      paragraph.textContent = "No public repositories are currently available.";

      message.appendChild(paragraph);

      githubContainer.appendChild(message);

      return;
    }

    githubContainer.appendChild(fragment);
  }

  /* =====================================================
       21. GITHUB ERROR HANDLING
    ===================================================== */

  function showGitHubError() {
    if (!githubContainer) {
      return;
    }

    githubContainer.innerHTML = "";

    githubContainer.setAttribute("aria-busy", "false");

    const errorCard = document.createElement("div");

    errorCard.className = "github-error-card";

    const message = document.createElement("p");

    message.textContent =
      "Unable to retrieve repository information right now. " +
      "You can still explore my public projects directly on GitHub.";

    const link = document.createElement("a");

    link.href = GITHUB_PUBLIC_PROFILE;

    link.target = "_blank";

    link.rel = "noopener noreferrer";

    link.textContent = "Visit my GitHub profile ↗";

    errorCard.appendChild(message);

    errorCard.appendChild(link);

    githubContainer.appendChild(errorCard);
  }

  /* =====================================================
       22. LOAD GITHUB PROFILE & REPOSITORIES
    ===================================================== */

  async function loadGitHubData() {
    if (!githubContainer || githubRequestStarted) {
      return;
    }

    githubRequestStarted = true;

    updateGitHubStatus("Connecting to GitHub", "loading");

    githubContainer.setAttribute("aria-busy", "true");

    try {
      /*
       * Fetch profile and owned repositories separately.
       * This lets repository loading succeed even if
       * the profile statistics request fails.
       */

      const results = await Promise.allSettled([
        fetchGitHubJSON(GITHUB_PROFILE_URL),

        fetchGitHubJSON(GITHUB_REPOSITORY_URL),
      ]);

      /* =========================================
               PROFILE INFORMATION
            ========================================= */

      const profileResult = results[0];

      if (profileResult.status === "fulfilled") {
        updateGitHubStats(profileResult.value);
      } else {
        console.warn(
          "GitHub profile statistics unavailable:",
          profileResult.reason,
        );
      }

      /* =========================================
               REPOSITORIES
            ========================================= */

      const repositoryResult = results[1];

      if (repositoryResult.status !== "fulfilled") {
        throw repositoryResult.reason;
      }

      const repositories = repositoryResult.value;

      if (!Array.isArray(repositories)) {
        throw new Error("Invalid GitHub repository response.");
      }

      /* Show public repositories only */

      const publicRepositories = repositories

        .filter(function (repository) {
          return repository && !repository.private;
        })

        .sort(function (a, b) {
          return (
            new Date(b.updated_at).getTime() - new Date(a.updated_at).getTime()
          );
        });

      /*
       * Automatically match:
       * - AcadTrack
       * - Barangay Tatalon MIS
       *
       * Their links are updated to the real URLs
       * returned by GitHub.
       */

      matchFeaturedProjectRepositories(publicRepositories);

      /* Render public GitHub cards */

      renderGitHubRepositories(publicRepositories);

      updateGitHubStatus("Live GitHub data", "connected");
    } catch (error) {
      console.error("GitHub API Error:", error);

      updateGitHubStatus("GitHub temporarily unavailable", "error");

      /* Keep project links usable */

      matchFeaturedProjectRepositories([]);

      showGitHubError();
    }
  }

  /* =====================================================
       23. LAZY LOAD GITHUB SECTION
    ===================================================== */

  const githubSection = document.getElementById("github");

  if (githubSection && "IntersectionObserver" in window) {
    const githubLoadObserver = new IntersectionObserver(
      function (entries, observer) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            loadGitHubData();

            observer.unobserve(entry.target);
          }
        });
      },

      {
        rootMargin: "250px 0px",
      },
    );

    githubLoadObserver.observe(githubSection);
  } else {
    loadGitHubData();
  }

  /* =====================================================
       24. COPY EMAIL
    ===================================================== */

  const copyEmailButton = document.getElementById("copy-email");

  const copyStatus = document.getElementById("copy-status");

  function fallbackCopyText(value) {
    const textarea = document.createElement("textarea");

    textarea.value = value;

    textarea.setAttribute("readonly", "");

    textarea.style.position = "fixed";

    textarea.style.left = "-9999px";

    textarea.style.top = "0";

    document.body.appendChild(textarea);

    textarea.select();

    textarea.setSelectionRange(0, textarea.value.length);

    let success = false;

    try {
      success = document.execCommand("copy");
    } catch (error) {
      success = false;
    }

    textarea.remove();

    return success;
  }

  if (copyEmailButton) {
    copyEmailButton.addEventListener("click", async function () {
      const email = copyEmailButton.getAttribute("data-email");

      if (!email) {
        return;
      }

      let success = false;

      try {
        if (navigator.clipboard && window.isSecureContext) {
          await navigator.clipboard.writeText(email);

          success = true;
        } else {
          success = fallbackCopyText(email);
        }
      } catch (error) {
        success = fallbackCopyText(email);
      }

      if (copyStatus) {
        copyStatus.textContent = success
          ? "Email address copied successfully."
          : "Unable to copy automatically. Please copy the email manually.";
      }

      copyEmailButton.textContent = success ? "Copied ✓" : "Try Again";

      window.setTimeout(function () {
        copyEmailButton.textContent = "Copy Email";
      }, 2500);
    });
  }

  /* =====================================================
       25. PROFILE IMAGE FALLBACK
    ===================================================== */

  const profileImage = document.querySelector(".profile-image");

  if (profileImage) {
    profileImage.addEventListener(
      "error",
      function () {
        const wrapper = profileImage.parentElement;

        profileImage.remove();

        if (!wrapper) {
          return;
        }

        const fallback = document.createElement("span");

        fallback.className = "profile-image-fallback";

        fallback.textContent = "SB";

        wrapper.appendChild(fallback);
      },

      { once: true },
    );
  }

  /* =====================================================
       26. COPYRIGHT YEAR
    ===================================================== */

  if (currentYear) {
    currentYear.textContent = new Date().getFullYear();
  }

  /* =====================================================
       27. EXTERNAL LINK SECURITY
    ===================================================== */

  document.querySelectorAll('a[target="_blank"]').forEach(function (link) {
    link.setAttribute("rel", "noopener noreferrer");
  });

  /* =====================================================
       28. INITIAL NAVIGATION
    ===================================================== */

  setActiveNavigation("home");
})();
